def set_paragraph_text(paragraph: Paragraph, text: str) -> None:
    if not paragraph.runs:
        paragraph.add_run(text)
        return
    paragraph.runs[0].text = text
    for run in paragraph.runs[1:]:
        run.text = ""


def replace_in_paragraphs(doc: Document) -> int:
    count = 0
    for p in doc.paragraphs:
        t = p.text
        if t in REPLACEMENTS:
            set_paragraph_text(p, REPLACEMENTS[t])
            count += 1
    return count


def _insert_paragraph_before(paragraph: Paragraph, text: str, bold: bool = False) -> Paragraph:
    new_p = OxmlElement("w:p")
    paragraph._p.addprevious(new_p)
    new_para = Paragraph(new_p, paragraph._parent)
    run = new_para.add_run(text)
    if bold:
        run.bold = True
    return new_para


def insert_sources_before_appendix(doc: Document) -> None:
    """Вставить список источников перед ПРИЛОЖЕНИЕ А."""
    anchor_para = None
    for p in doc.paragraphs:
        if p.text.strip().startswith("ПРИЛОЖЕНИЕ А"):
            anchor_para = p
            break
    if anchor_para is None:
        return

    _insert_paragraph_before(anchor_para, SOURCES_TITLE, bold=True)
    for i, source in enumerate(SOURCES, start=1):
        _insert_paragraph_before(anchor_para, f"{i}. {source}")


def update_toc_line(doc: Document) -> None:
    for p in doc.paragraphs:
        if p.text.strip() == "ЗАКЛЮЧЕНИЕ21":
            set_paragraph_text(p, "ЗАКЛЮЧЕНИЕ21")
            break
    for p in doc.paragraphs:
        if "ПРИЛОЖЕНИЕ А23" in p.text:
            set_paragraph_text(p, "СПИСОК ИСПОЛЬЗОВАННЫХ ИСТОЧНИКОВ22")
            break


def replace_appendix(doc: Document) -> None:
    start = None
    for i, p in enumerate(doc.paragraphs):
        if p.text.strip().startswith("ПРИЛОЖЕНИЕ А"):
            start = i
            break
    if start is None:
        return

    # Заголовок приложения
    set_paragraph_text(doc.paragraphs[start], APPENDIX_LINES[0])

    # Удалить старые абзацы приложения (с конца)
    while len(doc.paragraphs) > start + 1:
        p = doc.paragraphs[-1]
        if p._p.getparent() is not None:
            p._p.getparent().remove(p._p)

    anchor = doc.paragraphs[start]._p
    parent = anchor.getparent()
    for line in APPENDIX_LINES[1:]:
        new_p = deepcopy(anchor)
        parent.append(new_p)
        para = Paragraph(new_p, doc.paragraphs[start]._parent)
        set_paragraph_text(para, line)


def add_citation_patches(doc: Document) -> None:
    """Добавить ссылки там, где их ещё нет, по ключевым фразам."""
    patches = [
        ("Выбор C# и .NET обоснован", "Выбор C# и .NET [1] обоснован"),
        ("Выбор PostgreSQL обоснован", "Выбор PostgreSQL [3] обоснован"),
        ("Выбор Rider обоснован", "Выбор Rider обоснован"),
    ]
    for p in doc.paragraphs:
        t = p.text
        for old, new in patches:
            if old in t and new not in t:
                set_paragraph_text(p, t.replace(old, new))


def main() -> None:
    if not DOCX_PATH.exists():
        raise SystemExit(f"Не найден файл: {DOCX_PATH}")

    import shutil

    shutil.copy2(DOCX_PATH, BACKUP_PATH)
    doc = Document(str(DOCX_PATH))

    n = replace_in_paragraphs(doc)
    add_citation_patches(doc)
    update_toc_line(doc)
    insert_sources_before_appendix(doc)
    replace_appendix(doc)

    try:
        doc.save(str(DOCX_PATH))
        out = DOCX_PATH.name
    except PermissionError:
        alt = ROOT / "docs" / "Uchebnaya_Praktika_Otchet_updated.docx"
        doc.save(str(alt))
        out = alt.name
        print("Исходный файл занят (закройте Word). Сохранено в:", alt)
    print(f"Готово: заменено абзацев — {n}, резервная копия — {BACKUP_PATH.name}, результат — {out}")


if __name__ == "__main__":
    main()
